&lt;p style=&quot;margin-right:-14px; text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Saadet Partisi Genel Başkanı Mahmut Arıkan TBMM&amp;rsquo;de ger&amp;ccedil;ekleştirilen grup toplantısında konuştu.&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt; &amp;Uuml;retici ve emeklinin yaşadığı ekonomik darboğaza dikkat &amp;ccedil;eken Arıkan, NATO zirvesi hazırlıklarını işaret ederek &amp;quot;İktidar sorunları brandayla kapatıyor&amp;quot; dedi. İl il yayılan NATO protestosu yasaklarına &amp;quot;Br&amp;uuml;ksel&amp;#39;de serbest, Ankara&amp;#39;da yasak&amp;quot; s&amp;ouml;zleriyle tepki g&amp;ouml;steren Arıkan&amp;#39;ın en &amp;ccedil;arpıcı &amp;ccedil;ıkışı ise savunma sanayisi &amp;uuml;zerinden oldu. Trump&amp;#39;ın T&amp;uuml;rkiye&amp;#39;den taleplerinin konuşulmadığını vurgulayan Arıkan, k&amp;uuml;rs&amp;uuml;den &amp;ldquo;BlackRock adlı Amerikan fonu, Aselsan&amp;#39;ı mı almak istiyor?&amp;rdquo; sorusunu y&amp;ouml;neltti.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;margin-right:-14px; text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;BU İKTİDAR BRANDA İKTİDARIDIR!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Her hafta emeklimizden &amp;uuml;reticimize bu grup toplantımızda toplumun b&amp;uuml;t&amp;uuml;n kesimleriyle bir araya gelmeye gayret ediyoruz. Bir taraftan da onların gelmesini beklemeden her fırsatta Anadolu&amp;#39;yu karış karış dolaşıyoruz. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Her ne kadar iktidar işi g&amp;uuml;c&amp;uuml; bırakıp Ankara&amp;#39;daki NATO toplantısına odaklanmış olsa da; bizim g&amp;uuml;ndemimiz Anadolu, bizim g&amp;uuml;ndemimiz milletimiz. Bu hafta sonu da &amp;uuml;zerinden &amp;uuml;&amp;ccedil; bu&amp;ccedil;uk yıl ge&amp;ccedil;mesine rağmen hala depremin yaralarını sarmaya &amp;ccedil;alışan Adıyaman ilimizdeydik. Ankara&amp;#39;da; NATO toplantısı i&amp;ccedil;in, yoksulluğun &amp;uuml;zeri brandalarla kapatılmaya &amp;ccedil;alışılırken, bizler Adıyamanlı hemşehrilerimizin dertleri ile hemhal olduk.&lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Esnafımızla, &amp;ccedil;ift&amp;ccedil;ilerimizle, gen&amp;ccedil;lerimizle bir araya geldik. Ama bir dokunduk bin ah işittik. Bitmeyen yollar, bitmeyen sulama projeleri, devam eden altyapı sorunları, toz toprak i&amp;ccedil;erisinde bir Adıyaman g&amp;ouml;rd&amp;uuml;k. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Biz bunları g&amp;ouml;rd&amp;uuml;k ama Sayın Cumhurbaşkanı Adıyaman&amp;#39;a gittiğinde bunlar g&amp;ouml;r&amp;uuml;lmedi. Neden? &amp;Ccedil;&amp;uuml;nk&amp;uuml; o zaman da Adıyaman&amp;#39;ı brandalarla kapatmışlardı.&lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu iktidar branda iktidarıdır! Neden branda iktidarı diyoruz? &amp;Ccedil;&amp;uuml;nk&amp;uuml; bu iktidar; sorunları &amp;ccedil;&amp;ouml;zmeyi değil, &amp;ouml;rtmeyi marifet sayıyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sayın Cumhurbaşkanı Hatay&amp;#39;a gidecek branda, Adıyaman&amp;#39;a gidecek branda, şimdi de Trump gelecek diye b&amp;uuml;t&amp;uuml;n Ankara brandalarla &amp;ouml;rt&amp;uuml;l&amp;uuml;yor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ey AK Partililer; beceriksizliğinizi, ayıbınızı brandalarla &amp;ouml;rtemezsiniz. 25 yılın sonunda AK Parti iktidarının &amp;uuml;lkemizi getirdiği nokta budur. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sorunları branda ile &amp;ouml;rteceklerini sanıyorlar. İşte bizler o brandaların arkasında saklanmaya &amp;ccedil;alışılan Adıyaman&amp;#39;ın feryadını dinledik.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;BU &amp;Uuml;LKENİN &amp;Uuml;RETİCİSİNİ, K&amp;Uuml;RESEL SERMAYENİN İNSAFINA TERK ETTİLER&amp;rdquo; &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;Bakınız, Adıyaman&amp;rsquo;dan buraya elimde bir emanetle geldim rengini, kokusunu Adıyaman&amp;rsquo;ın bereketli topraklarından, değerini Adıyamanlının alın terinden alan t&amp;uuml;t&amp;uuml;n&amp;uuml; getirdim.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu elimde g&amp;ouml;rd&amp;uuml;ğ&amp;uuml;n&amp;uuml;z sadece bir tarım &amp;uuml;r&amp;uuml;n&amp;uuml; değildir; bu &amp;uuml;lkenin alın teridir, hafızasıdır, &amp;uuml;retim iradesidir. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Peşinen s&amp;ouml;yleyeyim elbette bizler de en az cumhurbaşkanı kadar t&amp;uuml;t&amp;uuml;n kullanımına karşıyız. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ancak buradaki mesele vatandaşın cebindeki sigara paketini almak değil, bu &amp;uuml;lkenin &amp;uuml;reticisini, k&amp;uuml;resel sermayenin insafına terk etmektir. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu &amp;uuml;lkede AK Parti iktidarından &amp;ouml;nce 500 bine yakın insan, t&amp;uuml;t&amp;uuml;n &amp;uuml;retiminden ge&amp;ccedil;imini sağlıyordu. Bug&amp;uuml;n bu rakam 35 binlere kadar d&amp;uuml;şt&amp;uuml;. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Peki &amp;uuml;retim dip yaparken, t&amp;uuml;ketim ne olmuş; Sayın cumhurbaşkanı t&amp;uuml;ketim konusunda &amp;ccedil;ok hassas, Biliyorsunuz sigara i&amp;ccedil;enlere kızıyor, azarlıyor, hatta cebindeki paketi alıp i&amp;ccedil;meme s&amp;ouml;z&amp;uuml; verdiriyor. Bunlar g&amp;uuml;zel hareketler. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ama bir de madalyonun &amp;ouml;b&amp;uuml;r y&amp;uuml;z&amp;uuml; var. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Yine AK Parti iktidarı d&amp;ouml;neminde, T&amp;uuml;rkiye&amp;#39;de yıllık sigara t&amp;uuml;ketimi 160 milyar adedi aşarak tarihin en y&amp;uuml;ksek miktarına ulaştı. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu arkadaşlar; Faize karşılar, &amp;uuml;lke faiz rekoru kırılıyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Enflasyona karşılar, &amp;uuml;lkede enflasyon rekoru kırılıyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Sigaraya karşılar, &amp;uuml;lkede sigara t&amp;uuml;ketiminde rekor kırılıyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Tam da bu noktada iktidara bir ricada bulunmak istiyoruz; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Allah rızası i&amp;ccedil;in siz bir şeye karşı olmayın.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu &amp;uuml;lkeye g&amp;ouml;lge etmeyin, başka ihsan istemiyoruz.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;ADIYAMANLI MUHLİS KAYBETTİ, VİRGİNİALI MORRİS KAZANDI&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;ldquo;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu &amp;uuml;lkede TEKEL vardı. Bu toprakların &amp;ccedil;ift&amp;ccedil;isinden t&amp;uuml;t&amp;uuml;n&amp;uuml; alır, bu &amp;uuml;lkenin fabrikalarında işlerdi. Samsun vardı, Bafra vardı, Maltepe vardı.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;TEKEL tasfiye edildi. Sonu&amp;ccedil;ta ne oldu? &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Adıyamanlı Muhlis kaybetti, Virginialı MORRİS kazandı. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Samsun&amp;#39;un yerini Monte Carlo, Bafra&amp;#39;nın yerini Winston markaları aldı. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Allah aşkına; bu mu sizin yerliliğiniz? &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu mu sizin milliliğiniz?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Yabancı karteller pazara h&amp;acirc;kim Kendi &amp;ccedil;ift&amp;ccedil;imiz kendi toprağında ka&amp;ccedil;ak&amp;ccedil;ı muamelesi g&amp;ouml;r&amp;uuml;yor, hapis cezası alıyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bu mu sizin adaletiniz? &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ahmed Arif&amp;#39;in dediği gibi; &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;quot;T&amp;uuml;t&amp;uuml;n iş&amp;ccedil;ileri yoksul, &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;T&amp;uuml;t&amp;uuml;n iş&amp;ccedil;ileri yorgun, &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Ama yiğit Pırıl- pırıl namuslu.&amp;quot;&lt;/span&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

