&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Y&amp;uuml;zde 82,9&amp;#39;u gelir dağılımını adaletsiz buluyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Bir başka acı ger&amp;ccedil;ek; pazartesi g&amp;uuml;n&amp;uuml; genel merkezimizde &amp;ouml;nemli bir buluşma ger&amp;ccedil;ekleştirdik. Bağımlılıkla m&amp;uuml;cadele eden Sivil Toplum Kuruluşu temsilcileri ve evlatları uyuşturucu belasına bulaşan ailelerle bir araya geldik. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

