&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;T&amp;uuml;rkiye&amp;rsquo;de bağımlı sayısı 16 milyona ulaşmış durumda. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Uyuşturucu kullanım yaşı DOKUZA kadar d&amp;uuml;şm&amp;uuml;ş arkadaşlar dokuza! &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;Okulların &amp;ouml;n&amp;uuml;nde &amp;ldquo;Jelibon&amp;rdquo; formunda tanesi 50 liraya, 100 liraya uyuşturucu satılıyor. Cezaevlerine pe&amp;ccedil;eteye emdirilmiş uyuşturucu sokup i&amp;ccedil;eride satılıyor. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

